var controller=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEditor.Animations.AnimatorController>("Assets/_Game/Animations/Shared/Chapter01Shared.controller");
return new{clips=controller.animationClips.Select(c=>new{c.name,c.isHumanMotion,path=UnityEditor.AssetDatabase.GetAssetPath(c)}).ToArray(),states=controller.layers[0].stateMachine.states.Select(s=>new{s.state.name,motion=s.state.motion==null?null:s.state.motion.name,path=UnityEditor.AssetDatabase.GetAssetPath(s.state.motion),transitions=s.state.transitions.Select(t=>new{target=t.destinationState==null?null:t.destinationState.name,t.duration,t.hasExitTime}).ToArray()}).ToArray(),actors=UnityEngine.Object.FindObjectsByType<UnityEngine.Animator>(UnityEngine.FindObjectsInactive.Include).Select(a=>new{a.name,controller=a.runtimeAnimatorController==null?null:a.runtimeAnimatorController.name}).ToArray()};
